package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import androidx.annotation.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.Fragment;import com.google.android.material.button.MaterialButton;import java.text.Normalizer;import java.util.*;
public class VerbCenterFragment extends Fragment{
 private WordRepository repo;private ProgressStore progress;private AudioPlayer audio;private Spinner verbSpinner,tenseSpinner;private TextView stats,title,meaning,tenseLabel,note,quizPrompt,feedback;private LinearLayout forms;private EditText quizInput;private MaterialButton check,next;private final List<String> lemmas=new ArrayList<>();private final Map<String,Word> reps=new LinkedHashMap<>();private String lemma,tense;private int quizPerson=0;private long started;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_verb_center,c,false);repo=WordRepository.get(requireContext());progress=new ProgressStore(requireContext());audio=new AudioPlayer(requireContext(),progress);verbSpinner=v.findViewById(R.id.spinner_verb);tenseSpinner=v.findViewById(R.id.spinner_tense);stats=v.findViewById(R.id.text_verb_stats);title=v.findViewById(R.id.text_verb_title);meaning=v.findViewById(R.id.text_verb_meaning);tenseLabel=v.findViewById(R.id.text_verb_tense);note=v.findViewById(R.id.text_verb_note);forms=v.findViewById(R.id.container_verb_forms);quizPrompt=v.findViewById(R.id.text_verb_quiz_prompt);feedback=v.findViewById(R.id.text_verb_feedback);quizInput=v.findViewById(R.id.edit_verb_answer);check=v.findViewById(R.id.button_verb_check);next=v.findViewById(R.id.button_verb_next);v.findViewById(R.id.button_verb_back).setOnClickListener(x->((MainActivity)requireActivity()).openPractice());buildVerbList();List<String> names=new ArrayList<>();for(String l:lemmas){Word w=reps.get(l);names.add(l+(w==null||w.chinese==null||w.chinese.isEmpty()?"":" · "+w.chinese));}ArrayAdapter<String> va=new ArrayAdapter<>(requireContext(),R.layout.item_spinner_text,names);va.setDropDownViewResource(R.layout.item_spinner_dropdown);verbSpinner.setAdapter(va);List<String> tn=new ArrayList<>();for(String t:VerbConjugator.tenseIds())tn.add(VerbConjugator.label(t));ArrayAdapter<String>ta=new ArrayAdapter<>(requireContext(),R.layout.item_spinner_text,tn);ta.setDropDownViewResource(R.layout.item_spinner_dropdown);tenseSpinner.setAdapter(ta);android.widget.AdapterView.OnItemSelectedListener listener=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View vv,int pos,long id){render();}};verbSpinner.setOnItemSelectedListener(listener);tenseSpinner.setOnItemSelectedListener(listener);check.setOnClickListener(x->grade());next.setOnClickListener(x->{quizPerson=(quizPerson+1)%6;showQuiz();});quizInput.setOnEditorActionListener((tv,a,e)->{if(a==EditorInfo.IME_ACTION_DONE){grade();return true;}return false;});stats.setText(lemmas.size()+" 个课程动词原形 · 5个核心时态 · 历史练习正确率 "+progress.auxiliaryAccuracy("verb_center")+"%");render();return v;}
 private void buildVerbList(){for(Word w:repo.all()){String l=(w.lemma==null||w.lemma.trim().isEmpty()?w.word:w.lemma).trim().toLowerCase(Locale.ROOT);if((l.endsWith("are")||l.endsWith("ere")||l.endsWith("ire"))&&!reps.containsKey(l))reps.put(l,w);}lemmas.addAll(reps.keySet());}
 private void render(){if(lemmas.isEmpty())return;int vi=Math.max(0,Math.min(verbSpinner.getSelectedItemPosition(),lemmas.size()-1));int ti=Math.max(0,Math.min(tenseSpinner.getSelectedItemPosition(),VerbConjugator.tenseIds().length-1));lemma=lemmas.get(vi);tense=VerbConjugator.tenseIds()[ti];Word w=reps.get(lemma);title.setText(lemma);meaning.setText(w==null?"":w.chinese);tenseLabel.setText(VerbConjugator.label(tense));note.setText(VerbConjugator.note(lemma,tense));String[] fs=VerbConjugator.forms(lemma,tense);forms.removeAllViews();String[] ps=VerbConjugator.persons();if(fs!=null)for(int n=0;n<6;n++){LinearLayout row=new LinearLayout(requireContext());row.setOrientation(LinearLayout.HORIZONTAL);row.setPadding(0,dp(6),0,dp(6));TextView p=new TextView(requireContext());p.setText(ps[n]);p.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_secondary));p.setTextSize(13);row.addView(p,new LinearLayout.LayoutParams(dp(76),ViewGroup.LayoutParams.WRAP_CONTENT));TextView f=new TextView(requireContext());f.setText(fs[n]);f.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_primary));f.setTextSize(17);f.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);row.addView(f,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));final String speak=fs[n].replace("/a","").replace("/e","");row.setOnClickListener(v->audio.speak(speak));forms.addView(row);}quizPerson=0;showQuiz();}
 private void showQuiz(){String[] fs=VerbConjugator.forms(lemma,tense);if(fs==null)return;quizPrompt.setText(VerbConjugator.persons()[quizPerson]+"  ______   ("+lemma+")");quizInput.setText("");quizInput.setEnabled(true);check.setEnabled(true);feedback.setText("");started=System.currentTimeMillis();}
 private void grade(){if(!quizInput.isEnabled())return;String[] fs=VerbConjugator.forms(lemma,tense);if(fs==null)return;String expected=fs[quizPerson];String actual=quizInput.getText()==null?"":quizInput.getText().toString();boolean ok=matches(actual,expected);long ms=Math.max(1,System.currentTimeMillis()-started);progress.recordAuxiliaryResult("verb_center",ok,ms);if(!ok){progress.recordGrammarResult("verb_agreement",false,ms);progress.recordErrorCause(ErrorCause.WORD_FORM,0,"verb_center",expected,actual,lemma+" · "+VerbConjugator.label(tense));}feedback.setText(ok?"✓ 正确":"✗ 正确答案："+expected);feedback.setTextColor(ContextCompat.getColor(requireContext(),ok?R.color.success:R.color.error));quizInput.setEnabled(false);check.setEnabled(false);audio.speak(expected.replace("/a","").replace("/e",""));stats.setText(lemmas.size()+" 个课程动词原形 · 历史练习正确率 "+progress.auxiliaryAccuracy("verb_center")+"%");}
 private boolean matches(String a,String b){String na=norm(a);if(b!=null&&b.contains("/a")){String base=b.replace("/a","");String alt=b.replace("o/a","a");return na.equals(norm(base))||na.equals(norm(alt));}if(b!=null&&b.contains("/e")){String base=b.replace("/e","");String alt=b.replace("i/e","e");return na.equals(norm(base))||na.equals(norm(alt));}return na.equals(norm(b));}private String norm(String s){if(s==null)return"";return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ITALIAN).replaceAll("[^a-z ]"," ").replaceAll("\\s+"," ").trim();}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}@Override public void onDestroyView(){if(audio!=null)audio.release();super.onDestroyView();}
}
